<?php defined('BASEPATH') OR exit('No direct script access allowed');class Meeting_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function list_rows($table,$org,$p,$pp,$filters){$this->db->from($table)->where('organization_id',$org);foreach($filters as $k=>$v)if($v!==NULL&&$v!=='')$this->db->where($k,$v);$n=$this->db->count_all_results();$this->db->where('organization_id',$org);foreach($filters as $k=>$v)if($v!==NULL&&$v!=='')$this->db->where($k,$v);$r=$this->db->order_by('created_at','DESC')->limit($pp,($p-1)*$pp)->get($table)->result_array();$fn=$table==='meetings'?'meeting_view':'action_view';return array('items'=>array_map(array($this,$fn),$r),'pagination'=>array('page'=>$p,'perPage'=>$pp,'total'=>$n,'totalPages'=>(int)ceil($n/$pp)));}function meeting($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('meetings')->row_array();return $r?$this->meeting_view($r):NULL;}function save_meeting($id,$org,$uid,$d){$now=date('Y-m-d H:i:s');if(!$id){$id=$this->uuid();$r=array('id'=>$id,'organization_id'=>$org,'channel_id'=>$d['channelId']??NULL,'title'=>$d['title'],'description'=>$d['description']??NULL,'status'=>'SCHEDULED','scheduled_start'=>isset($d['scheduledStart'])?date('Y-m-d H:i:s',strtotime($d['scheduledStart'])):NULL,'created_by_id'=>$uid,'notetaker_agent_id'=>$d['notetakerAgentId']??NULL,'notetaker_status'=>'IDLE','decisions'=>'[]','metadata'=>'{}','created_at'=>$now,'updated_at'=>$now);$this->db->insert('meetings',$r);}else{$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('meetings')->row_array();if(!$r)return NULL;$map=array('title'=>'title','description'=>'description','status'=>'status','scheduledStart'=>'scheduled_start','startedAt'=>'started_at','endedAt'=>'ended_at','summary'=>'summary');$set=array('updated_at'=>$now);foreach($map as $i=>$o)if(isset($d[$i]))$set[$o]=strpos($i,'At')!==FALSE?date('Y-m-d H:i:s',strtotime($d[$i])):($i==='status'?strtoupper($d[$i]):$d[$i]);$this->db->where('id',$id)->update('meetings',$set);}return $this->meeting($id,$org);}function transcript($id,$org,$text,$final){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('meetings')->row_array();if(!$r)return FALSE;$new=trim(($r['transcript']?$r['transcript']."\n":'').$text);$this->db->where('id',$id)->update('meetings',array('transcript'=>$new,'notetaker_status'=>$final?'COMPLETED':'RECORDING','updated_at'=>date('Y-m-d H:i:s')));return TRUE;}function action($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('action_items')->row_array();return $r?$this->action_view($r):NULL;}function save_action($id,$org,$uid,$d){$now=date('Y-m-d H:i:s');if(!$id){$id=$this->uuid();$r=array('id'=>$id,'organization_id'=>$org,'meeting_id'=>$d['meetingId']??NULL,'channel_id'=>$d['channelId']??NULL,'title'=>$d['title'],'description'=>$d['description']??NULL,'status'=>$d['status']??'OPEN','priority'=>$d['priority']??'MEDIUM','due_date'=>isset($d['dueDate'])?date('Y-m-d H:i:s',strtotime($d['dueDate'])):NULL,'assignee_id'=>$d['assigneeId']??NULL,'agent_assignee_id'=>$d['agentAssigneeId']??NULL,'created_by_id'=>$uid,'source_message_id'=>$d['sourceMessageId']??NULL,'metadata'=>'{}','created_at'=>$now,'updated_at'=>$now);$this->db->insert('action_items',$r);}else{$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('action_items')->row_array();if(!$r)return NULL;$map=array('title'=>'title','description'=>'description','status'=>'status','priority'=>'priority','dueDate'=>'due_date','assigneeId'=>'assignee_id','agentAssigneeId'=>'agent_assignee_id');$set=array('updated_at'=>$now);foreach($map as $i=>$o)if(array_key_exists($i,$d))$set[$o]=$i==='dueDate'&&$d[$i]?date('Y-m-d H:i:s',strtotime($d[$i])):$d[$i];if(($d['status']??'')==='DONE')$set['completed_at']=$now;$this->db->where('id',$id)->update('action_items',$set);}return $this->action($id,$org);}function delete_action($id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->delete('action_items');return $this->db->affected_rows()>0;}function meeting_view($r){return array('id'=>$r['id'],'title'=>$r['title'],'description'=>$r['description'],'status'=>strtolower($r['status']),'channelId'=>$r['channel_id'],'scheduledStart'=>$r['scheduled_start'],'startedAt'=>$r['started_at'],'endedAt'=>$r['ended_at'],'notetakerAgentId'=>$r['notetaker_agent_id'],'notetakerStatus'=>strtolower($r['notetaker_status']),'transcript'=>$r['transcript'],'summary'=>$r['summary'],'decisions'=>json_decode($r['decisions'],TRUE)?:array(),'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']);}function action_view($r){return array('id'=>$r['id'],'title'=>$r['title'],'description'=>$r['description'],'status'=>strtolower($r['status']),'priority'=>strtolower($r['priority']),'meetingId'=>$r['meeting_id'],'channelId'=>$r['channel_id'],'dueDate'=>$r['due_date'],'assigneeId'=>$r['assignee_id'],'agentAssigneeId'=>$r['agent_assignee_id'],'createdById'=>$r['created_by_id'],'completedAt'=>$r['completed_at'],'aiGenerated'=>FALSE,'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
